import SwiftUI

/// Official red filmstrip-C artwork supplied for Cinemana iOS.
/// Generated by scripts/make_app_icon.swift from the bundled original image.
/// This replaces the earlier hand-drawn Canvas approximation.
struct CinemanaGlyph: View {
    var body: some View {
        Image("CinemanaArtwork")
            .resizable()
            .interpolation(.high)
            .aspectRatio(contentMode: .fit)
            .accessibilityLabel("Cinemana iOS")
    }
}

/// Brand-first startup overlay; catalog network requests run underneath.
struct CinemanaSplashView: View {
    var body: some View {
        GeometryReader { geometry in
            ZStack {
                Color(red: 0.045, green: 0.008, blue: 0.018)
                RadialGradient(
                    colors: [Color(red: 0.31, green: 0.015, blue: 0.045),
                             Color(red: 0.055, green: 0.005, blue: 0.015)],
                    center: .center, startRadius: 15,
                    endRadius: max(geometry.size.width, geometry.size.height) * 0.7
                )
                VStack(spacing: 14) {
                    CinemanaGlyph()
                        .frame(width: min(250, geometry.size.width * 0.62),
                               height: min(250, geometry.size.width * 0.62))
                        .shadow(color: .red.opacity(0.35), radius: 25)
                    Text("CINEMANA")
                        .font(.system(size: 25, weight: .black, design: .rounded))
                        .tracking(3.5)
                        .foregroundStyle(.white)
                    Text("iOS")
                        .font(.system(size: 13, weight: .semibold, design: .rounded))
                        .tracking(3)
                        .foregroundStyle(.white.opacity(0.78))
                    ProgressView()
                        .tint(Color(red: 1.0, green: 0.22, blue: 0.28))
                        .padding(.top, 20)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            }
            .ignoresSafeArea()
        }
        .background(.black)
        .accessibilityElement(children: .combine)
        .accessibilityLabel("Starting Cinemana iOS")
    }
}
